    ('technology-and-devices', 'hard', 'technology-and-devices-hard', ARRAY['operating system|hệ điều hành','wireless connection|kết nối không dây','cloud storage|lưu trữ đám mây','factory settings|cài đặt gốc','software update|cập nhật phần mềm','security settings|cài đặt bảo mật','device compatibility|khả năng tương thích thiết bị','technical support|hỗ trợ kỹ thuật','data transfer|truyền dữ liệu','battery life|thời lượng pin','troubleshooting guide|hướng dẫn khắc phục sự cố','user interface|giao diện người dùng','peripheral device|thiết bị ngoại vi','malfunctioning|đang hoạt động lỗi','authentication|xác thực','encryption|mã hóa','firmware|phần sụn','configuration|cấu hình','cybersecurity|an ninh mạng','accessibility feature|tính năng hỗ trợ tiếp cận'])
), expanded AS (
  SELECT bank.topic_slug, bank.difficulty, bank.lesson_key,
         split_part(entry.value, '|', 1) AS content_en,
         split_part(entry.value, '|', 2) AS meaning_vi,
         entry.ordinality::integer AS bank_order
  FROM word_banks bank
  CROSS JOIN LATERAL unnest(bank.entries) WITH ORDINALITY AS entry(value, ordinality)
), numbered AS (
  SELECT expanded.*,
         'phase6-' || expanded.topic_slug || '-' || expanded.difficulty || '-word-' || lpad(expanded.bank_order::text, 2, '0') AS item_key,
         row_number() OVER (PARTITION BY topic.id, expanded.difficulty ORDER BY expanded.bank_order) AS sort_offset,
         lesson.id AS lesson_id,
         COALESCE((SELECT max(item.sort_order) FROM public.communication_lesson_items item WHERE item.lesson_id = lesson.id), 0) AS max_sort_order
  FROM expanded
  JOIN public.communication_topics topic ON topic.slug = expanded.topic_slug
  JOIN public.communication_lessons lesson ON lesson.lesson_key = expanded.lesson_key
)
INSERT INTO public.communication_lesson_items
  (item_key, lesson_id, item_type, content_en, meaning_vi, sort_order)
SELECT item_key, lesson_id, 'word', content_en, meaning_vi,
       max_sort_order + sort_offset::integer
FROM numbered
ON CONFLICT (item_key) DO UPDATE SET
  lesson_id = EXCLUDED.lesson_id,
  item_type = EXCLUDED.item_type,
  content_en = EXCLUDED.content_en,
